WITH metrics AS (SELECT id, store_name, city, region, opened_date, SUM(sqft) OVER (PARTITION BY region ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, AVG(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS sqft_avg_6 FROM stores) SELECT id, store_name, city, region, opened_date, running_sqft, sqft_avg_6, CASE WHEN city RLIKE '^(Bangkok|Tokyo)$' THEN 'PRIORITY' WHEN city RLIKE '^(Chiang Mai|New York)$' THEN 'CORE' ELSE 'EXTENDED' END AS city_zone FROM metrics ORDER BY sqft_avg_6 DESC
